), grid as (
    insert into public.regions (parent_id, code, name, region_type, geometry, source, is_supported, is_sample)
    select district.id, cell.code, 'H3 cell ' || substr(cell.code, 4), 'grid',
           extensions.ST_Multi(extensions.ST_SetSRID(extensions.ST_GeomFromGeoJSON(cell.boundary), 4326)),
           'H3 resolution 9 sample grid', false, true
    from cell
    join public.regions district on district.code = cell.district and district.is_sample = true
    on conflict (code) do update
    set parent_id = excluded.parent_id, geometry = excluded.geometry
    where public.regions.is_sample = true
    returning id, code
)
insert into public.region_data
    (region_id, metric, numeric_value, unit, evidence_type, source, sample_size, limitations, is_sample)
select grid.id, fact.metric, fact.value, fact.unit, fact.evidence_type, 'Jejak mock heatmap fixture v2',
       fact.sample_size, 'Synthetic cell value for map testing; not observed evidence.', true
from cell
join grid on grid.code = cell.code
cross join lateral (values
    ('estimated_office_workers', cell.workers, 'workers', 'estimated', cell.buildings),
    ('estimated_office_workers_low', cell.workers_low, 'workers', 'estimated', cell.buildings),
    ('estimated_office_workers_high', cell.workers_high, 'workers', 'estimated', cell.buildings),
    ('housing_listing_count', cell.listings, 'listings', 'observed', null),
    ('median_monthly_rent_idr', cell.rent, 'IDR/month', 'derived', cell.listings)
) as fact(metric, value, unit, evidence_type, sample_size)
where fact.value is not null
on conflict (region_id, metric, period_start, period_end, source) do update
set numeric_value = excluded.numeric_value,
    sample_size = excluded.sample_size,
    limitations = excluded.limitations
where public.region_data.is_sample = true;

commit;
